package com.henson.jarvis.phone;
import android.net.Uri;import org.json.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
public final class OpenAIClient {
 private final TokenVault vault;private Pending pending;private volatile HttpURLConnection activeResponse;
 public void cancel(){HttpURLConnection c=activeResponse;if(c!=null)c.disconnect();}
 private static final String AUTH="https://auth.openai.com/api/accounts/";
 private static final String RESOURCE="https://api.openai.com/v1";
 private static class Pending{String client,state,nonce,verifier,redirect,subject;long created;}
 public OpenAIClient(TokenVault vault){this.vault=vault;}
 private static String enc(String value)throws Exception{return URLEncoder.encode(value,"UTF-8");}
 private static String form(String... values)throws Exception{StringBuilder b=new StringBuilder();for(int i=0;i<values.length;i+=2){if(b.length()>0)b.append('&');b.append(enc(values[i])).append('=').append(enc(values[i+1]));}return b.toString();}
 private static HttpURLConnection connection(String url,String method,String bearer)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(20000);c.setReadTimeout(90000);c.setRequestMethod(method);c.setInstanceFollowRedirects(false);if(bearer!=null)c.setRequestProperty("Authorization","Bearer "+bearer);return c;}
 private static JSONObject json(String url,String method,String bearer,String body,boolean form)throws Exception{HttpURLConnection c=connection(url,method,bearer);try{if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type",form?"application/x-www-form-urlencoded":"application/json");try(OutputStream out=c.getOutputStream()){out.write(body.getBytes(StandardCharsets.UTF_8));}}int code=c.getResponseCode();if(code<200||code>=300)throw apiError(code);try(InputStream in=c.getInputStream()){return new JSONObject(read(in,2000000));}}finally{c.disconnect();}}
 private static String read(InputStream in,int max)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(bytes.size()+n>max)throw new Exception("Response exceeded the safe size limit.");bytes.write(buffer,0,n);}return bytes.toString("UTF-8");}
 private static Exception apiError(int code){return new Exception(code==401?"ChatGPT sign-in expired. Reconnect your account.":code==429?"ChatGPT usage limit or temporary rate limit reached. Manage usage or try later. No paid fallback was used.":code==403?"ChatGPT plan access is not available for this account or client. Reconnect to review permissions.":"OpenAI request failed (HTTP "+code+"). No paid fallback was used.");}
 public synchronized JSONObject status()throws Exception{JSONObject data=vault.read();JSONObject account=data.getJSONObject("accounts").optJSONObject(data.optString("active"));return account==null||!account.has("access_token")?new JSONObject().put("connected",false):new JSONObject().put("connected",true).put("email",account.optString("email")).put("model",account.optString("model")).put("modelName",account.optString("modelName"));}
 public synchronized JSONObject savedAccounts()throws Exception{return vault.read().getJSONObject("accounts");}
 public synchronized String authorize(String selected,String redirect)throws Exception{JSONObject all=vault.read().getJSONObject("accounts");JSONObject old=selected==null?null:all.optJSONObject(selected);Pending p=new Pending();p.client=old==null?"dynamic_agent_client":selected;p.subject=old==null?null:old.getString("subject");p.state=OAuthChecks.random();p.nonce=OAuthChecks.random();p.verifier=OAuthChecks.random();p.redirect=redirect;p.created=System.currentTimeMillis();pending=p;
  String query=form("client_id",p.client,"ext_agent_host_id",vault.host(),"response_type","code","redirect_uri",redirect,"scope","openid profile email offline_access resource.invoke chatgpt.tokens.use.direct","resource",RESOURCE,"state",p.state,"nonce",p.nonce,"code_challenge_method","S256","code_challenge",OAuthChecks.challenge(p.verifier));
  if(old==null)query+="&"+form("agent_name_hint","Henson JARVIS");else if(old.has("id_token"))query+="&"+form("id_token_hint",old.getString("id_token"));return AUTH+"authorize?"+query;
 }
 public synchronized void complete(Uri callback)throws Exception{Pending p=pending;if(p==null||System.currentTimeMillis()-p.created>600000)throw new Exception("Sign-in attempt expired. Return to JARVIS and reconnect.");OAuthChecks.same(p.state,callback.getQueryParameter("state"));pending=null;if(callback.getQueryParameter("error")!=null)throw new Exception("ChatGPT sign-in was cancelled or plan permission was declined.");String client=callback.getQueryParameter("client_id");if("dynamic_agent_client".equals(p.client)){if(client==null||client.equals("dynamic_agent_client")||client.isEmpty()||client.length()>200)throw new Exception("ChatGPT client registration did not finish.");}else{if(client!=null)OAuthChecks.same(p.client,client);client=p.client;}
  String code=callback.getQueryParameter("code");if(code==null||code.length()>12000)throw new Exception("Missing sign-in code.");JSONObject tokens=json(AUTH+"oauth/token","POST",null,form("grant_type","authorization_code","client_id",client,"code",code,"code_verifier",p.verifier,"redirect_uri",p.redirect,"resource",RESOURCE),true);
  OAuthChecks.scopes(tokens.optString("scope"));JSONObject keys=json("https://auth.openai.com/.well-known/jwks.json","GET",null,null,false);JSONObject identity=OAuthChecks.verify(tokens.getString("id_token"),keys,client,p.nonce,System.currentTimeMillis()/1000);
  if(p.subject!=null)OAuthChecks.same(p.subject,identity.getString("sub"));JSONObject data=vault.read();JSONObject accounts=data.getJSONObject("accounts");JSONObject previous=accounts.optJSONObject(client);if(previous!=null)OAuthChecks.same(previous.getString("subject"),identity.getString("sub"));
  JSONObject saved=new JSONObject(tokens.toString()).put("client_id",client).put("subject",identity.getString("sub")).put("email",identity.optString("email","ChatGPT account")).put("expires_at",System.currentTimeMillis()+tokens.getLong("expires_in")*1000);accounts.put(client,saved);data.put("active",client);vault.write(data);
 }
 private JSONObject active()throws Exception{JSONObject data=vault.read();String client=data.optString("active");JSONObject account=data.getJSONObject("accounts").optJSONObject(client);if(account==null||!account.has("access_token"))throw new Exception("Tap Continue with ChatGPT to connect your plan.");if(account.optLong("expires_at")<System.currentTimeMillis()+60000){JSONObject fresh=json(AUTH+"oauth/token","POST",null,form("grant_type","refresh_token","client_id",client,"refresh_token",account.getString("refresh_token"),"resource",RESOURCE),true);String scopes=fresh.optString("scope",account.optString("scope"));OAuthChecks.scopes(scopes);account.put("access_token",fresh.getString("access_token")).put("refresh_token",fresh.getString("refresh_token")).put("scope",scopes).put("expires_at",System.currentTimeMillis()+fresh.getLong("expires_in")*1000);vault.write(data);}OAuthChecks.scopes(account.optString("scope"));return account;}
 public synchronized JSONArray models()throws Exception{JSONObject account=active();JSONArray all=json(RESOURCE+"/models","GET",account.getString("access_token"),null,false).getJSONArray("models");JSONArray visible=new JSONArray();for(int i=0;i<all.length();i++){JSONObject m=all.getJSONObject(i);if("list".equals(m.optString("visibility")))visible.put(new JSONObject().put("slug",m.getString("slug")).put("display_name",m.getString("display_name")));}if(visible.length()==0)throw new Exception("No ChatGPT models are available to this account.");return visible;}
 public synchronized void chooseModel(String slug)throws Exception{JSONArray models=models();for(int i=0;i<models.length();i++){JSONObject m=models.getJSONObject(i);if(slug.equals(m.getString("slug"))){saveModel(slug,m.getString("display_name"));return;}}throw new Exception("Model is unavailable for this ChatGPT account.");}
 private void saveModel(String slug,String name)throws Exception{JSONObject data=vault.read();data.getJSONObject("accounts").getJSONObject(data.getString("active")).put("model",slug).put("modelName",name);vault.write(data);}
 public synchronized JSONObject ask(JSONObject body)throws Exception{JSONObject account=active();JSONArray models=models();String slug=account.optString("model"),name="";boolean found=false;for(int i=0;i<models.length();i++)if(slug.equals(models.getJSONObject(i).getString("slug"))){found=true;name=models.getJSONObject(i).getString("display_name");}if(!found){slug=models.getJSONObject(0).getString("slug");name=models.getJSONObject(0).getString("display_name");saveModel(slug,name);}JSONArray messages=body.getJSONArray("messages");if(messages.length()>40)throw new Exception("Conversation is too long.");JSONArray input=new JSONArray();for(int i=0;i<messages.length();i++){JSONObject m=messages.getJSONObject(i);String role=m.getString("role"),text=m.getString("content");if(!Arrays.asList("user","assistant").contains(role)||text.length()>12000)throw new Exception("Invalid conversation.");input.put(new JSONObject().put("role",role).put("content",text));}
  String prefs=body.optString("preferences");if(prefs.length()>3000)prefs=prefs.substring(0,3000);JSONObject payload=new JSONObject().put("model",slug).put("store",false).put("stream",true).put("input",input).put("instructions","You are JARVIS, Christopher Sean's personal assistant. Address the user as sir naturally. Use concise, refined British phrasing. Be accurate and acknowledge uncertainty. You cannot send messages, control accounts, or execute external actions. Never claim actions you did not execute. User preferences: "+prefs);
  HttpURLConnection c=connection(RESOURCE+"/responses","POST",account.getString("access_token"));activeResponse=c;c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("Accept","text/event-stream");try{try(OutputStream out=c.getOutputStream()){out.write(payload.toString().getBytes(StandardCharsets.UTF_8));}if(c.getResponseCode()!=200)throw apiError(c.getResponseCode());boolean completed=false;StringBuilder answer=new StringBuilder();try(BufferedReader reader=new BufferedReader(new InputStreamReader(c.getInputStream(),StandardCharsets.UTF_8))){String line;StringBuilder event=new StringBuilder();while((line=reader.readLine())!=null){if(line.startsWith("data:")){event.append(line.substring(5).trim());continue;}if(!line.isEmpty()||event.length()==0)continue;String text=event.toString();event.setLength(0);if(text.equals("[DONE]"))continue;JSONObject e=new JSONObject(text);String type=e.optString("type");if(type.equals("response.output_text.delta"))answer.append(e.optString("delta"));if(answer.length()>100000)throw new Exception("ChatGPT answer exceeded the safe size limit.");if(type.equals("response.completed"))completed=true;if(type.equals("response.failed")||type.equals("response.incomplete")||type.equals("error"))throw new Exception("ChatGPT could not complete this answer. Your plan may have reached a usage limit; review Manage usage. No paid fallback was used.");}}
  if(!completed||answer.toString().trim().isEmpty())throw new Exception("ChatGPT stream ended without a completed answer. Please retry.");return new JSONObject().put("answer",answer.toString()).put("model",slug).put("modelName",name);
  }finally{activeResponse=null;c.disconnect();}
 }
 public synchronized void signOut()throws Exception{JSONObject data=vault.read();JSONObject a=data.getJSONObject("accounts").optJSONObject(data.optString("active"));if(a==null)return;boolean revoked=true;try{if(a.has("refresh_token")){HttpURLConnection c=connection(AUTH+"oauth/revoke","POST",null);try{c.setDoOutput(true);c.setRequestProperty("Content-Type","application/x-www-form-urlencoded");try(OutputStream out=c.getOutputStream()){out.write(form("token",a.getString("refresh_token"),"token_type_hint","refresh_token","client_id",a.getString("client_id")).getBytes(StandardCharsets.UTF_8));}revoked=c.getResponseCode()==200;}finally{c.disconnect();}}}catch(Exception e){revoked=false;}for(String key:new String[]{"access_token","refresh_token","id_token","expires_at"})a.remove(key);data.remove("active");vault.write(data);if(!revoked)throw new Exception("Signed out locally. Remote revocation was not confirmed; disconnect JARVIS in ChatGPT Settings.");}
}
